print("pluginUsage:",{k:(v.get('usageCount'),v.get('lastUsedAt')) for k,v in d.get('pluginUsage',{}).items()})
files=sorted(glob.glob(home+'/.claude/projects/*/*.jsonl'),key=os.path.getmtime,reverse=True)[:50]
import datetime
