tools=collections.Counter(); skills=collections.Counter(); cmds=collections.Counter()
hooks=collections.defaultdict(list); den=collections.Counter(); uses={}
for f in files:
  for line in open(f,errors='ignore'):
    try:o=json.loads(line)
    except:continue
    t=o.get('type')
    if t=='assistant':
      c=o.get('message',{}).get('content')
      if isinstance(c,list):
        for b in c:
          if b.get('type')=='tool_use':
            n=b['name']
            uses[b['id']]=(n,b.get('input',{}))
            if n.startswith('mcp__'): tools[n.split('__')[1]]+=1
            if n=='Skill': skills[b['input'].get('skill')]+=1
    elif t=='user':
      s=json.dumps(o.get('message',{}).get('content',''))
      for m in re.findall(r'<command-name>/?([^<]+)</command-name>',s): cmds[m]+=1
      k=o.get('toolDenialKind')
      if k and k not in('interrupted','cancelled'):
        c=o.get('message',{}).get('content')
        if isinstance(c,list):
          for b in c:
            if b.get('type')=='tool_result' and b.get('tool_use_id') in uses:
              n,i=uses[b['tool_use_id']]
              key=n if n!='Bash' else 'Bash:'+' '.join(i.get('command','').split()[:2])
              den[(key,k)]+=1
    elif t=='attachment':
      a=o.get('attachment',{})
      if a.get('type','').startswith('hook') and 'durationMs' in a:
        hooks[(a.get('hookEvent'),a.get('hookName'),a.get('type'),a.get('timedOut'))].append(a['durationMs'])
print("mcp calls by server:",dict(tools))
print("Skill tool:",dict(skills))
print("slash:",dict(cmds))
print("denials:",den.most_common(15))
for k,v in sorted(hooks.items(),key=lambda x:-max(x[1]))[:10]:
  print(k,len(v),"avg",sum(v)//len(v),"max",max(v))

